                    break
            A[pivot_row], A[j] = A[j], A[pivot_row]
            for j in range(n):
                if i == j:
                    A[i][j] /= A[i][i]
                else:
                    A[j][i] /= A[i][i]
                    for k in range(i, n):
                        A[j][k] -= A[i][k]
            rank += 1
        return rank

    def spearman_correlation(ranks1, ranks2):
